import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"2019-10-21 :: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2019-10-21 :: Ceph Orchestration Meeting","date":"2019-10-21T00:00:00.000Z","updated":"2019-10-22T00:00:00.000Z","tags":["Ceph Orchestrator","Rook","sage daemon","Pull Request","Inventory","OSD","Upgrade","Configuration"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-10-21_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2019/2019-10-21_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780459816000}'),l={name:"posts/2019/2019-10-21_-_-_Ceph_Orchestration_Meeting.md"};function i(n,e,s,g,h,p){return t(),a("div",null,[...e[0]||(e[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2019年10月21日（具体日期未提及）</p><p><strong>会议地点</strong>： 线上会议</p><p><strong>参会人员</strong>： 未知（会议纪要中未提及具体姓名）</p><p><strong>会议主题</strong>：</p><ul><li>Ceph Orchestrator相关议题</li><li>Rook项目进展</li><li>安全守护进程（sage daemon）相关讨论</li></ul><h3 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h3><p><strong>Ceph Orchestrator相关议题</strong></p><ul><li><strong>预览驱动器组功能</strong>： 新的Pull Request允许在仪表板和编排器中预览驱动器组，但需要依赖Rook的卷库存功能。</li><li><strong>Rook项目进展</strong>： 讨论了Rook 1.1.3版本，计划修复OSD配置和升级问题。</li><li><strong>安全守护进程（sage daemon）</strong>： 讨论了sage daemon的功能和范围，以及是否将其作为独立项目或集成到Ceph源代码树中。</li></ul><p><strong>Rook项目进展</strong></p><ul><li><strong>Rook 1.1.3版本</strong>： 计划明天发布，主要修复了OSD配置和升级问题。</li><li><strong>OSD配置问题</strong>： 配置覆盖没有被正确应用，需要进一步调查和修复。</li><li><strong>OSD升级问题</strong>： 需要确保在升级过程中始终进行OSD pod的同步。</li></ul><p><strong>安全守护进程（sage daemon</strong>）</p><ul><li><strong>功能</strong>： sage daemon用于启动和管理安全守护进程，包括创建密钥环、配置守护进程等。</li><li><strong>范围</strong>： 讨论了sage daemon的功能和范围，以及是否将其作为独立项目或集成到Ceph源代码树中。</li><li><strong>独立项目</strong>： 一些参与者认为sage daemon应该作为一个独立项目进行开发，以便更好地控制其版本和功能。</li><li><strong>集成到Ceph源代码树中</strong>： 一些参与者认为sage daemon应该集成到Ceph源代码树中，以便更好地与Ceph生态系统整合。</li></ul><h3 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h3><ul><li><strong>Rook 1.1.3版本</strong>： 计划明天发布。</li><li><strong>sage daemon</strong>： 需要进一步讨论和决策。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li><strong>Rook 1.1.3版本</strong>： 发布Rook 1.1.3版本。</li><li><strong>sage daemon</strong>： <ul><li>发布sage daemon的设计文档。</li><li>讨论sage daemon的集成方案。</li><li>确定sage daemon的开发和发布计划。</li></ul></li></ul><h3 id="计算机科学-ceph相关领域英文原文关键词" tabindex="-1">计算机科学/ceph相关领域英文原文关键词 <a class="header-anchor" href="#计算机科学-ceph相关领域英文原文关键词" aria-label="Permalink to &quot;计算机科学/ceph相关领域英文原文关键词&quot;">​</a></h3><ul><li>Ceph Orchestrator</li><li>Rook</li><li>sage daemon</li><li>Pull Request</li><li>Inventory</li><li>OSD</li><li>Upgrade</li><li>Configuration</li><li>Dependency</li><li>Scope</li><li>Integration</li></ul>',19)])])}const u=o(l,[["render",i]]);export{_ as __pageData,u as default};
